#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-component-design-locked.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-component-design-locked.mjs
 *
 * @version 2
 * @updated 2026-06-05
 *
 * Enforces the design-first phase order for design-system primitives. Components are
 * discovered via the shared `_discover-components.mjs` helper (path-agnostic:
 * components/ui/, generic components/, and feature-located <feature>/components/), NOT
 * only src/components/ui/. For every component folder that contains
 * .tsx source, __specs__/design.md must exist AND carry the lock marker:
 *
 *     <!-- design-locked: YYYY-MM-DD -->
 *
 * The marker is inserted by the USER on approval. Spec-writer NEVER self-signs.
 *
 * The verifier ALSO checks git history: if any .tsx file's first commit
 * precedes the design.md's first commit, the slice violated phase order
 * (code shipped before design). Git history is consulted only when the
 * repository is reachable; if git fails (shallow clone, no history), the
 * temporal check is skipped with a warning.
 *
 * Usage:
 *   node verify-component-design-locked.mjs [src-root]
 *   default src-root: "src"
 *
 * Exit: 0 if all components are design-locked OR no components found;
 *       1 if any component has source without a locked design.md.
 *
 * Per COMPONENT_CREATION.yaml.verifiers.verify-component-design-locked.
 */

import { readFileSync, existsSync } from "node:fs";
import { join, relative, basename } from "node:path";
import { execSync } from "node:child_process";
import { discoverComponents } from "./_discover-components.mjs";
import { applyExceptions } from "./_load-exceptions.mjs";

const RULE_ID = "verify-component-design-locked";
const SRC_ROOT = process.argv[2] || "src";
const REPO_ROOT = process.cwd();
const absRoot = join(REPO_ROOT, SRC_ROOT);

const LOCK_MARKER_REGEX = /<!--\s*design-locked:\s*\d{4}-\d{2}-\d{2}(\s+by:(user|agent))?\s*-->/;

if (!existsSync(absRoot)) {
  process.stdout.write(
    `✅ verify-component-design-locked — no ${SRC_ROOT}/ in this repo; nothing to check.\n`,
  );
  process.exit(0);
}

const componentFolders = discoverComponents(absRoot).map((c) => c.dir);

if (componentFolders.length === 0) {
  process.stdout.write(
    `✅ verify-component-design-locked — no design-system components found under ${SRC_ROOT}/ (components/ui, components/, or feature-located components/).\n`,
  );
  process.exit(0);
}

const violations = [];

function firstCommitIso(filePath) {
  try {
    // NB: no --follow. Rename detection traces near-identical sibling components
    // (e.g. Textarea ↔ TextField) back to the other's first commit, producing a
    // false "code shipped before design" for files that actually landed together.
    // The actual add-commit of each file is what the design-before-code check needs.
    const iso = execSync(
      `git log --diff-filter=A --format=%aI -- ${JSON.stringify(filePath)}`,
      { cwd: REPO_ROOT, stdio: ["ignore", "pipe", "ignore"] },
    )
      .toString()
      .trim()
      .split("\n")
      .filter(Boolean)
      .pop();
    return iso || null;
  } catch {
    return null;
  }
}

// Collect every design-lock violation for ONE component folder, so a per-feature
// exception.yaml can waive them (with a logged reason) before the global tally.
function checkFolder(folder, rel, name) {
  const local = [];
  const designPath = join(folder, "__specs__", "design.md");
  const designRel = relative(REPO_ROOT, designPath);

  if (!existsSync(designPath)) {
    local.push(
      `${rel}: missing __specs__/design.md (required before any ${name}.tsx is committed)`,
    );
    return local;
  }

  let content;
  try {
    content = readFileSync(designPath, "utf8");
  } catch (e) {
    local.push(`${designRel}: read error — ${e.message}`);
    return local;
  }

  if (!LOCK_MARKER_REGEX.test(content)) {
    local.push(
      `${designRel}: missing lock marker \`<!-- design-locked: YYYY-MM-DD -->\` (user inserts after approving; spec-writer never self-signs)`,
    );
    return local;
  }

  // Temporal check: design.md must be first-committed no later than the source .tsx.
  const sourceTsx = join(folder, `${name}.tsx`);
  const designAddedAt = firstCommitIso(designPath);
  const sourceAddedAt = firstCommitIso(sourceTsx);

  if (designAddedAt && sourceAddedAt) {
    if (new Date(sourceAddedAt).getTime() < new Date(designAddedAt).getTime()) {
      local.push(
        `${rel}: ${name}.tsx (first committed ${sourceAddedAt}) precedes ${designRel} (first committed ${designAddedAt}). Code shipped before design — violates phase order.`,
      );
    }
  }
  return local;
}

for (const folder of componentFolders) {
  const rel = relative(REPO_ROOT, folder);
  const name = basename(folder);
  const local = checkFolder(folder, rel, name);
  violations.push(
    ...applyExceptions({ dir: folder, ruleId: RULE_ID, violations: local, rel }),
  );
}

if (violations.length === 0) {
  process.stdout.write(
    `✅ verify-component-design-locked — ${componentFolders.length} component(s) checked; all design-locked.\n`,
  );
  process.exit(0);
}

process.stderr.write(
  `❌ verify-component-design-locked: ${violations.length} violation(s)\n\n`,
);
for (const v of violations) process.stderr.write(`  ${v}\n`);
process.stderr.write(
  `\nPer COMPONENT_CREATION.yaml.phases, source MUST NOT land before design.md is locked.\n` +
    `Template: ~/.claude/standards/templates/component-design.md.template\n` +
    `User inserts the lock marker after approving the design.\n`,
);
process.exit(1);
